package com.nigson.acceptance.market;
import com.nigson.commerce.market.*;
import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import java.time.*;
import java.net.*;
import java.net.http.*;
import static org.assertj.core.api.Assertions.*;
public final class MarketHttpAcceptance {
 private MarketHttpAcceptance(){}
 public static void run(ConfigurableApplicationContext app,HttpClient http,String base)throws Exception{
  if(System.getenv("NIGSON_TEST_MARKET")==null)return;var sessions=app.getBean(JdbcSessionTrust.class);var cookies=new ArrayList<String>();var tokens=new ArrayList<String>();
  try(var f=new MarketFixture(app.getBean(JdbcTemplate.class),app.getBean(MarketService.class))){
   for(UUID party:List.of(f.finance,f.publisher)){String issuer=f.jdbc.queryForObject("SELECT identity_issuer FROM commerce.party WHERE id=?",String.class,party);var flow=sessions.begin("/account");sessions.consume(flow.sessionId(),flow.flow().state());String token=JdbcSessionTrust.opaque();tokens.add(token);String session=sessions.authenticate(flow.sessionId(),new SessionRecord(1,party,issuer,party.toString(),Instant.now(),Instant.now(),"synthetic-access","synthetic-refresh",Instant.now().plusSeconds(300),token,SessionRecord.TokenState.READY));cookies.add("__Host-nigson-session="+session);}
   String uri=base+"/api/v1/markets",create=base+"/api/v1/staff/markets";assertThat(send(http,HttpRequest.newBuilder(URI.create(uri)).GET()).statusCode()).isEqualTo(200);assertThat(send(http,HttpRequest.newBuilder(URI.create(uri+"?enabled=true")).GET()).statusCode()).isEqualTo(400);assertThat(send(http,HttpRequest.newBuilder(URI.create(uri)).header("Authorization","Bearer browser-token").GET()).statusCode()).isEqualTo(401);String code="SYNTH_"+UUID.randomUUID().toString().substring(0,8).toUpperCase(),body=EventCodec.JSON.writeValueAsString(Map.of("code",code,"name","Synthetic HTTP market","currency","NGN")),key=UUID.randomUUID().toString();assertThat(send(http,mutation(create,null,null,key,body,false)).statusCode()).isEqualTo(401);assertThat(send(http,mutation(create,cookies.get(1),tokens.get(1),key,body,false)).statusCode()).isEqualTo(403);assertThat(send(http,mutation(create,cookies.getFirst(),"wrong",key,body,false)).statusCode()).isEqualTo(401);
   var created=send(http,mutation(create,cookies.getFirst(),tokens.getFirst(),key,body,false));assertThat(created.statusCode()).isEqualTo(201);UUID market=UUID.fromString(EventCodec.JSON.readTree(created.body()).get("id").asString());f.markets.add(market);assertThat(created.headers().firstValue("ETag")).hasValue("\"0\"");assertThat(created.headers().firstValue("Cache-Control")).hasValue("no-store");assertThat(EventCodec.JSON.readTree(created.body()).get("taxPolicy").isEmpty()).isTrue();assertThat(send(http,mutation(create,cookies.getFirst(),tokens.getFirst(),key,body,false)).body()).isEqualTo(created.body());assertThat(send(http,HttpRequest.newBuilder(URI.create(uri)).GET()).body()).isEqualTo("[]");
   UUID book=f.book("RETAIL","NGN",-60,0,true);String bookUri=create+"/"+market+"/retail-price-book",bookBody=EventCodec.JSON.writeValueAsString(Map.of("priceBookId",book,"reason","Synthetic HTTP reviewed book"));assertThat(send(http,mutation(bookUri,cookies.getFirst(),tokens.getFirst(),"missing-version",bookBody,true)).statusCode()).isEqualTo(400);var selected=send(http,mutation(bookUri,cookies.getFirst(),tokens.getFirst(),"book",bookBody,true).header("If-Match","\"0\""));assertThat(selected.statusCode()).isEqualTo(200);assertThat(selected.headers().firstValue("ETag")).hasValue("\"1\"");assertThat(send(http,mutation(bookUri,cookies.getFirst(),tokens.getFirst(),"stale",bookBody,true).header("If-Match","\"0\"")).statusCode()).isEqualTo(412);
   String restriction=base+"/api/v1/staff/products/"+f.product+"/markets/"+market,restrictionBody=EventCodec.JSON.writeValueAsString(Map.of("eligible",true,"reason","Synthetic HTTP product eligibility"));var changed=send(http,mutation(restriction,cookies.get(1),tokens.get(1),"eligible",restrictionBody,true).header("If-Match","\"0\""));assertThat(changed.statusCode()).isEqualTo(200);assertThat(changed.headers().firstValue("ETag")).hasValue("\"1\"");assertThat(send(http,mutation(restriction,cookies.get(1),tokens.get(1),"eligible",restrictionBody,true).header("If-Match","\"0\"")).body()).isEqualTo(changed.body());assertThat(send(http,mutation(restriction,cookies.getFirst(),tokens.getFirst(),"wrong-role",restrictionBody,true).header("If-Match","\"1\"")).statusCode()).isEqualTo(403);
   assertThat(app.getBean(io.micrometer.core.instrument.MeterRegistry.class).find("nigson.market.commands").tag("operation","CREATE").counter().count()).isEqualTo(1);f.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=?",f.finance);assertThat(send(http,mutation(create,cookies.getFirst(),tokens.getFirst(),key,body,false)).statusCode()).isEqualTo(403);
  }finally{for(String cookie:cookies)sessions.logout(cookie.substring(cookie.indexOf('=')+1));}
 }
 static HttpRequest.Builder mutation(String uri,String cookie,String csrf,String key,String body,boolean put){var r=HttpRequest.newBuilder(URI.create(uri)).header("Idempotency-Key",key).header("Content-Type","application/json");if(cookie!=null)r.header("Cookie",cookie);if(csrf!=null)r.header("X-CSRF-TOKEN",csrf);return r.method(put?"PUT":"POST",HttpRequest.BodyPublishers.ofString(body));}
 static HttpResponse<String> send(HttpClient http,HttpRequest.Builder request)throws Exception{return http.send(request.timeout(Duration.ofSeconds(10)).build(),HttpResponse.BodyHandlers.ofString());}
}
